-- Killing-blow ("fatality") messages for damage spells (fierymud-rs #134).
--
-- Legacy lib/misc/messages carries a death record per spell (attacker / victim / room) that replaces the
-- normal hit line when the spell kills. AbilityMessages.kill_to_caster / kill_to_victim / kill_to_room
-- hold them; the runtime sends them instead of success_to_* on a killing blow.
-- Run AFTER the muditor db push that adds the three columns.
--
-- Keyed by Ability.plain_name (ids differ between dev and prod); abilities missing from the database
-- are skipped; an ability with no AbilityMessages row gets one. Idempotent: rows whose three values
-- already match are not touched, so a re-run changes 0 rows.

INSERT INTO "AbilityMessages" (ability_id, kill_to_caster, kill_to_victim, kill_to_room)
SELECT a.id, v.to_caster, v.to_victim, v.to_room
FROM (VALUES
       ('ACID_BREATH', '<b:green>Your wash of acid sweeps {target.name} away in liquid form.</>', '<b:green>You are dissolved in {actor.name}''s wash of acid.</>', '<b:green>{target.name} is dissolved in {actor.name}''s wash of acid.</>'),
       ('ACID_BURST', '<magenta>{target.name} </><u:black>howls</><magenta> as {target.his} skin boils away in your bath of </><b:magenta>a</><b:yellow>c</><yellow>i</><b:red>d</><red>...</>', '<magenta>You feel excruciating pain as </><green>a</><b:green>c</><green>i</><b:green>d burns away your flesh...</>', '<magenta>{target.name} is doused in burning </><green>a</><b:green>c</><green>i</><b:green>d, melting {target.him}!</>'),
       ('ACID_FOG', '<green>{target.name} burns to death in your cloud of acid!</>', '<green>You burn to death in {actor.name}''s cloud of acid!!</>', '<green>{target.name} burns to death in {actor.name}''s cloud of acid!</>'),
       ('ANCESTRAL_VENGEANCE', 'Your ancestors drag {target.name} into the spirit world forever, screaming!', '{actor.name}''s ancestors drag you screaming into the spirit world forever!', '{actor.name}''s ancestors drag {target.name} into the spirit world forever, screaming!'),
       ('BALEFUL_POLYMORPH', '{target.name} turns inside out and <b:red>EXPLODES!</>', 'You turn inside out and <b:red>EXPLODE!</>', '{target.name} turns inside out and <b:red>EXPLODES!</>'),
       ('BIGBYS_CLENCHED_FIST', 'Your <b:yellow>Bigby''s Fist</> <u>OBLITERATES</> {target.name}!', 'You are <u>SMASHED</> to death by {actor.name}''s <b:yellow>Bigby''s Fist</>!', 'The <u>splattered remains</> of {target.name} is smeared all over the place by {actor.name}''s <b:yellow>Bigby''s Fist</>!'),
       ('BURNING_HANDS', 'You have <red>burned</> {target.name} to death!', 'You have been <red>burned to death</> by {actor.name}!', '{actor.name} has <red>burned</> {target.name} to death!'),
       ('CALL_LIGHTNING', 'Your lightning bolt kills {target.name}!', 'You are <b:blue>electrocuted</> to death by a <b:blue>lightning bolt</> sent by {actor.name}!', 'The dead body of {target.name} sizzles in the heat from a <b:blue>lightning bolt</> sent by {actor.name}!'),
       ('CAUSE_CRITIC', 'As you grab {target.name}''s body, all life in {target.his} body ceases.', 'You feel your heart stop as {actor.name} touches you.', '{actor.name} grabs {target.name}, causing {target.his} life to cease.'),
       ('CAUSE_LIGHT', 'As you grab {target.name}''s body, all life in {target.his} body ceases.', 'You feel your heart stop as {actor.name} touches you.', '{actor.name} grabs {target.name}, causing {target.his} life to cease.'),
       ('CAUSE_SERIOUS', 'As you grab {target.name}''s body, all life in {target.his} body ceases.', 'You feel your heart stop as {actor.name} touches you.', '{actor.name} grabs {target.name}, causing {target.his} life to cease.'),
       ('CHAIN_LIGHTNING', '<blue>Your lightning consumes {target.name}, leaving a charred corpse.</>', '<blue>Your body is consumed in the torrent of lightning...</>', '<blue>{target.name} is consumed by the waves of lightning, leaving a charred corpse.</>'),
       ('CHILL_TOUCH', 'You <b:blue>chill</> {target.name}, remember to put flowers on {target.his} grave...', 'You <b:blue>feel chilled</> by {actor.name} and then you feel no more -- R.I.P.', '{actor.name} <u>touches</> {target.name} who slumps to the ground as a dead lump, <b:blue>rather chilly isn''t it</>?'),
       ('CIRCLE_OF_DEATH', '<b:black>{target.name} is utterly consumed by your circle of death!</>', '<b:black>You are utterly consumed by the circle of death...</>', '<b:black>{target.name} is utterly consumed by the circle of deathly magic!</>'),
       ('CIRCLE_OF_FIRE', NULL::text, '<red>You are burned to death upon attempting to pass through the </><b:red>circle of fire.</>', '<red>{target.name} burns up as {target.he} passes through the </><b:red>circle of fire.</>'),
       ('CLOUD_OF_DAGGERS', '<red>{target.name} is fatally ripped apart by your </><b:black>cloud of daggers!</>', '<red>You are ripped apart by {actor.name}''s </><b:black>cloud of daggers!!</>', '<red>The </><b:black>cloud of daggers</> <red>rips apart {target.name}!</>'),
       ('COLOR_SPRAY', 'Your spray of color killed {target.name}!!', 'Your head is filled with all the colors of the rainbow before it bursts!', '{actor.name} makes {target.name} into a colorful corpse!'),
       ('CONE_OF_COLD', '<b:white>You see</> {target.name}''s <b:white>flesh peel off as your </><b:blue>icy blast</> <b:white>rips {target.him} to death!</>', '<b:white>Your flesh peels off as {actor.name}''s </><b:blue>icy blast</> <b:white>rips you to death!</>', '<b:white>{target.name} is torn away where {target.he} stands as {actor.name}''s </><b:blue>icy blast</> peels {target.his} flesh away!'),
       ('CREMATE', '<yellow>{target.name} hasn''t the time to scream as you engulf {target.him} in the </><red>burning </><u:red>inferno.</>', '<yellow>Your death is quick and painless in {actor.name}''s massive inferno.</>', '<yellow>{target.name} is </><red>consumed</><yellow> in the massive burning inferno!</>'),
       ('DECAY', '{target.name} shrivels up under your power!', 'Deterioration spreads through your body like a cancer...', '{target.name} withers away under {actor.name}''s deadly magic...'),
       ('DEGENERATION', 'You dry up the last of {target.name}''s flesh, leaving {target.him} an empty husk.', 'Your body ceases to function as {actor.name} withers the last of it.', '{target.name} slumps over dead as {actor.name} withers the last of {target.his} body.'),
       ('DESTROY_UNDEAD', 'Feeling your powerful blast, {target.name}''s rotting body explodes into large chunks.', 'Your body explodes as {actor.name} blasts you with {actor.his} holy might.', '{actor.name}''s holy blast shatters {target.name}''s rotting body into dust.'),
       ('DETONATION', 'You incinerate a <yellow>boulder</>, which <red>tears relentlessly </><yellow>through {target.name}.</>', '{actor.name} incinerates a <yellow>boulder</>, throwing <yellow>shards of rock </><red>tearing through </><yellow>you!</>', '{actor.name} incinerates a <yellow>boulder</>, throwing <yellow>shards of rock </><red>tearing through </><yellow>{target.name}.</>'),
       ('DISCORPORATE', 'The last of {target.name}''s bonds are undone, and {target.he} falls in pieces.', '{actor.name} dissolves your strength and your motivation, and you are undone.', '{target.name} falls apart.'),
       ('DISINTEGRATE', '<b:green>Your intense beam of destruction turns {target.name} to a pile of ash.</>', '<b:green>The intense beam of destruction sent from {actor.name} turns you to a pile of ash.</>', '<b:green>{actor.name}''s intense beam of destruction turns {target.name} to a pile of ash.</>'),
       ('DISPEL_EVIL', '{target.name} is dissolved by your goodness.', '{actor.name} dissolves you, you regret having been so evil, and die...', '{actor.name} completely dissolves {target.name}!'),
       ('DISPEL_GOOD', '{target.name} is dissolved by your evil.', '{actor.name} dissolves you -- the price paid for leading a good life -- you die...', '{actor.name} completely dissolves {target.name}!'),
       ('DISPEL_MAGIC', '{target.name} is stripped of all energy, and falls down inert.', '{actor.name} deletes your ego, leaving you utterly nonexistent.', '{target.name} falls down and is still.'),
       ('DIVINE_BOLT', '<white>Your holy bolt pierces {target.name} fatally.</>', '<white>{actor.name}''s holy bolt strikes deep into your soul, causing death.</>', '<white>{actor.name}''s holy bolt dispatches {target.name}.</>'),
       ('DIVINE_RAY', '<b:white>Your divine ray of light shows {target.name} the error of {target.his} ways.</>', '<b:white>{actor.name}''s divine ray pierces your soul, showing you the error of your ways.</>', '<b:white>{actor.name}''s divine ray of light shows {target.name} the error of {target.his} ways.</>'),
       ('DOOM', '<b:black>{target.name} is overwhelmed by the insects and buried under a carpet of living death!</>', '<b:black>You are overwhelmed by the insects and buried under a carpet of living death!</>', '<b:black>{target.name} is overwhelmed by the insects and buried under a carpet of living death!</>'),
       ('EARTHQUAKE', 'The earth opens beneath {target.name}''s feet and swallows {target.him} whole!', 'The earth opens beneath your feet and swallows you whole!', 'The earth opens beneath {target.name}''s feet and swallows {target.him} whole!'),
       ('ENERGY_DRAIN', '{target.name} crumples as you kill {target.him} by draining {target.his} energy!', 'As {actor.name} drains your last energy you look forward to the peace of the graveyard...', '{actor.name} drains the energy of {target.name} who crumples as a lifeless husk!'),
       ('EXORCISM', '<b:yellow>Your massive spiritual onslaught rips through {target.name}''s soul!</>', '<b:yellow>Your soul is torn to shreds by {actor.name}''s massive spiritual onslaught.</>', '<b:yellow>{actor.name}''s massive spiritual onslaught rips through {target.name}''s soul!</>'),
       ('FIREBALL', 'Your <red>fireball</> hits {target.name} with full force, causing an <b:black>immediate death</>!', 'As you <red>burst into flames of death</> {actor.name} grins evilly...', 'The heat from a fireball from {actor.name} turns {target.name} into a charred corpse!'),
       ('FIRESTORM', '<b:black>Your gout of </><b:red>fire</><b:black> consumes {target.name}, leaving a charred corpse.</>', '<b:black>{actor.name}''s gout of </><b:red>fire</><b:black> consumes you, leaving you as a charred corpse.</>', '<b:black>{target.name} vanishes in the gout of </><b:red>flames</><b:black>, leaving only a charred corpse.</>'),
       ('FIRE_BREATH', '<red>{target.name} burns to a crisp in the gout of fire.</>', '<red>You are burned to a crisp by {actor.name}''s gout of fire.</>', '<red>{actor.name} burns {target.name} to a crispy corpse by {actor.his} gout of fire.</>'),
       ('FIRE_DARTS', '<yellow>Your </><red>fire dart </><yellow>pierces {target.name}''s body, causing death.</>', '<yellow>You are pierced by {target.name}''s </><red>fire dart</><yellow>... you collapse.</>', '<yellow>{actor.name}''s</><red> fire dart</><yellow> pierces {target.name}''s</><red> body, causing death.</>'),
       ('FLAMESTRIKE', 'Your column of flame turns {target.name} to a pile of ash.', '{actor.name}''s column of flame turns you to a pile of ash.', '{actor.name}''s column of flame turns {target.name} to a pile of ash.'),
       ('FLOOD', '<b:blue>{target.name} is washed away and drowned in your furious flood.</>', '<b:blue>Your are washed away, slowly drowned in the massive flood.</>', '<b:blue>{target.name} is washed away and drowned in {actor.name}''s massive flood.</>'),
       ('FRACTURE_SHRAPNEL', 'The fragments shred {target.name}''s flesh!', 'The shards rip through your flesh, shredding it to pieces!', 'The fragmented shards rip {target.name}''s body to pieces!'),
       ('FREEZE', '<b:cyan>{target.name} is encased in a massive block of ice, permanently.</>', '<b:cyan>You are encased in a massive block of ice, permanently.</>', '<b:cyan>{target.name} is encased in a massive block of ice, permanently.</>'),
       ('FREEZING_WIND', '<b:cyan>Your piercing wind has frozen {target.name} solid.</>', '<b:cyan>{actor.name}''s piercing wind freezes you solid.</>', '<b:cyan>{actor.name}''s piercing wing freezes {target.name} solid.</>'),
       ('FROST_BREATH', '<b:blue>{target.name} freezes solid as all life in {target.his} body ceases.</>', '<b:blue>You are frozen solid! Your life slowly fades through the foggy ice...</>', '<b:blue>{actor.name}''s frosty torrent freezes {target.name} solid, killing {target.him} instantly.</>'),
       ('FULL_HARM', 'Enraged by your gods, you leap upon {target.name} and rip {target.his} skull and spine from {target.his} torso!', 'The last thing you see is the sky growing dark as {actor.name} hoists your skull into the air!', '{actor.name} looking somewhat possessed, leaps upon {target.name} ripping {target.his} skull and spine from {target.his} torso!'),
       ('GAS_BREATH', '<b:green>Your cloud of noxious gas overwhelms {target.name}.</>', '<b:green>You are overwhelmed by {actor.name}''s noxious cloud.</>', '<b:green>{actor.name}''s noxious gas overwhelms {target.name}.</>'),
       ('HARM', 'As you finish the incantation of the spell, {target.name} falls dead due to the amount of harm {target.he} takes!', 'You feel light-headed as {actor.name} completes a spell, which causes you so much harm that you are no more.', 'As {actor.name} touches {target.him}, {target.name} takes the full brunt of a harm spell and collapses.  Dead.'),
       ('HELLFIRE_BRIMSTONE', '<red>The conflagration of hellish </><b:black>gas</><red> and </><b:red>fire</><red> has claimed {target.name}''s soul!</>', '<red>The conflagration of hellish </><b:black>gas</><red> and </><b:red>fire</><red> has claimed your soul!</>', '<red>The conflagration of hellish </><b:black>gas</><red> and </><b:red>fire</><red> has claimed {target.name}''s soul!</>'),
       ('HELL_BOLT', '<red>Your bolt from hell slays {target.name}.</>', '<red>{actor.name}''s bolt from hell slays you.</>', '<red>{actor.name}''s bolt from hell slays {target.name}.</>'),
       ('HOLY_WORD', '<b:white>Your word of power is the last thing {target.name} hears.</>', '<b:white>{actor.name}''s word of power is the last thing you hear as your soul is torn apart.</>', '<b:white>{actor.name}''s word of power rends {target.name}''s soul to shreds.</>'),
       ('ICEBALL', '<b:cyan>Your iceball crushes {target.name} hard, dealing a fatal blow.</>', '<b:cyan>{actor.name}''s iceball impacts your body, dealing fatal damage.</>', '<b:cyan>{actor.name}''s iceball impacts {target.name} with a crushing blow!</>'),
       ('ICE_DARTS', '<yellow>Your </><cyan>ice dart </><yellow>pierces {target.name}''s body, causing death.</>', '<yellow>You are pierced by {target.name}''s </><cyan>ice dart</><yellow>... you collapse.</>', '<yellow>{actor.name}''s</><cyan> ice dart</><yellow> pierces {target.name}''s</><cyan> body, causing death.</>'),
       ('ICE_SHARDS', '<u>You cut the last bits of {target.name} to pieces with your shards.</>', '<u>The last of your internal organs are stripped away by {actor.name}''s shards.</>', '<u>{actor.name} shreds the last bits of {target.name} into tiny lifeless pieces.</>'),
       ('ICE_STORM', 'You grin as a layer of ice encases {target.name} causing {target.his} immediate demise!', 'A layer of ice encases you causing your immediate demise!', '{actor.name} grins as a layer of ice encases {target.name} causing {target.his} immediate demise!'),
       ('IMMOLATE', '<red>{target.name} finally succumbs to your </><b:red>hungry flames</><red>.</>', '<red>The </><b:red>burning</><red>! The </><b:magenta>pain</><red>! You collapse, yearning for </><b:black>death...</>', '<b:red>{target.name}''s burns are too serious to go on living...</>'),
       ('IRON_MAIDEN', 'A deathly iron maiden encloses {target.name}, screams are heard, then nothing...', 'You cry out as spikes pierce your organs and your wounds gush blood...', 'A deathly iron maiden encloses {target.name}, screams are heard, then nothing...'),
       ('LESSER_EXORCISM', '<yellow>Your spiritual onslaught rips through {target.name}''s soul!</>', '<yellow>Your soul is torn to shreds by {actor.name}''s spiritual onslaught.</>', '<yellow>{actor.name}''s spiritual onslaught rips through {target.name}''s soul!</>'),
       ('LIGHTNING_BOLT', 'Your <b:blue>lightning bolt</> shatters {target.name} to pieces!', 'You feel enlightened by the <b:blue>lightning bolt</> {actor.name} sends, and then all is darkness -- R.I.P.!', '{target.name} receives the full blast of a <b:blue>lightning bolt</> from {actor.name}... and is no more.'),
       ('LIGHTNING_BREATH', '<blue>{target.name} is smitten by your lightning breath.</>', '<blue>You are electrocuted by {actor.name}''s lightning breath.</>', '<blue>{target.name} convulses into a heap of burnt flesh after being smitten by {actor.name}''s lightning breath.</>'),
       ('MAGIC_MISSILE', 'The <b:yellow>magic missile</> tears away the remaining life of {target.name}!', 'You only have time to notice {actor.name} uttering strange sounds <b:black>before everything is dark</>!', 'The <b:yellow>magic missile</> sent by {actor.name} causes {target.name} to stagger and collapse in a lifeless heap!'),
       ('MELT', '<magenta>{target.name}''s exterior glows </><red>red hot</><magenta>, then melts away leaving only a viscous puddle.</>', '<magenta>Your flesh glows </><red>red hot</><magenta>, then begins to melt off your bones...</>', '<magenta>{target.name}''s exterior glows </><red>red hot</><magenta>, then melts away leaving only a viscous puddle.</>'),
       ('METEORSWARM', '<red>{target.name} is </><u:red>blasted</><red> to bits by a </><u:red>massive flaming </><u:yellow>meteorite</><u:red>.</>', '<red>You are </><u:red>smashed</><red> into little bits by a </><u:red>huge flaming </><u:yellow>meteorite.</>', '<red>{actor.name} blasts {target.name} into little bits with a </><u:red>huge flaming </><u:yellow>meteorite!</>'),
       ('MOONBEAM', '{target.name} falls into a lifeless heap, hoarfrost sprouting from {target.his} frigid skin.', 'All goes black as icy crystals pierce your brain.', '{actor.name} drives the life from {target.name}, who topples frozen to the ground.'),
       ('NIGHTMARE', 'You drive {target.name} well past the brink of madness, and {target.he} gives up {target.his} life.', 'You endure a seeming eternity of horror, but mercifully your heart ceases its rhythm.', 'Blood pours from every orifice as {target.name} endures a final <magenta>nightmare</> courtesy of {actor.name}!'),
       ('ON_FIRE', NULL::text, '<b:black>The </><b:red>fire </><b:black>dies away as it consumes the last of your living flesh.</>', '<b:red>{target.name} collapses as the fire consumes {target.his} life.</>'),
       ('PHOSPHORIC_EMBERS', 'Your <b:white>burning embers</> ate all the way through {target.name}.', 'The <b:white>embers</> burn right into your core...', '{target.name} has burned entirely away from within.'),
       ('POISON', NULL::text, 'Poison burns intensely in your veins... you shiver... you die.', '{target.name} has a shudders one last time and dies a painful death.'),
       ('POSITIVE_FIELD', 'You pulled so much charge out of {target.name} that {target.his} fell down dead!', '{actor.name} motions toward you, and a <white>bright blast</> of <b:blue>electricity</> makes everything go dark...', '{actor.name} causes a <b:blue>searing </><b:white>arc</> of <b:blue>electricity</> to knock {target.name} down for good!'),
       ('PYRE', '<red>{target.name} is enveloped by your flames!</>', '<red>The flames surrounding {actor.name} flare, burning you to a crisp!</>', '<red>The flames around {actor.name} flare up, burning {target.name} to a cirps!</>'),
       ('SEVERANCE', '{target.name}''s cord is snapped like a taut thread!', 'Your silver cord breaks with a sound like thunder.', '{target.name}''s cord is snapped like a taut thread!'),
       ('SHOCKING_GRASP', '{target.name} dies while looking rather shocked!', '{actor.name} shocks you.  Unfortunately your heart can''t stand it...', '{actor.name} reveals with a shock that {target.name} has left {target.his} body!'),
       ('SOUL_REAVER', ' {target.name} cries out with bloodshot eyes, clasps {target.his} chest, and dies.', ' Every horror descends at once, and your heart explodes.', ' {target.name} reaches pitifully for {target.his} heart as {target.he} crumples to the ground.'),
       ('SOUL_TAP', 'You smile inwardly as you tap the last of {target.name}''s life, ending it.', 'You feel {actor.name} tapping the last of your life force...and then you feel nothing.', '{actor.name} taps the last of {target.name}''s life, banishing {target.his} soul from this realm.'),
       ('SPIRIT_ARROWS', 'The <b:white>spirit arrow</> tears away the remaining spirit of {target.name}!', 'You only have time to notice {actor.name} uttering strange sounds <b:black>before everything is dark</>!', 'The <b:white>spirit arrow</> sent by {actor.name} causes {target.name} to stagger and collapse in a lifeless heap!'),
       ('SPIRIT_RAY', '<u>Spirit energy lances through {target.name}, tearing their soul asunder!</>', '<u>Your soul is impaled by {actor.name}''s spirit ray and </><b:u:white>SHATTERS!!</>', '<u>Spirit energy lances through {target.name}, tearing their soul asunder!</>'),
       ('STYGIAN_ERUPTION', '<b:black>Your hellish blast has burnt {target.name} to ashes.</>', '<b:black>{actor.name}''s hellish blast has burnt you to ashes.</>', '<b:black>{actor.name}''s hellish blast has burnt {target.name} to ashes.</>'),
       ('SUNRAY', '<b:yellow>{target.name}''s torso explodes into </><b:black>ashes</><b:yellow> when skewered by your deadly sunray!</>', '<b:yellow>Your torso explodes into </><b:black>ashes</><b:yellow> when skewered by {actor.name}''s deadly sunray!</>', '<b:yellow>{target.name}''s torso explodes into </><b:black>ashes</><b:yellow> when skewered by {actor.name}''s deadly sunray!</>'),
       ('SUPERNOVA', '<b:red>Your shock wave of </><red>fire</><b:red> blows {target.name}''s body to </><b:black>burnt</><b:red>, </><red>bloody </><b:red>pieces.</>', '<b:red>{actor.name}''s shock wave of </><red>fire</><b:red> blows your body to </><b:black>burnt</><b:red>, </><red>bloody </><b:red>pieces.</>', '<b:red>{actor.name}''s shock wave of </><red>fire</><b:red> blows {target.name}''s body to </><b:black>burnt</><b:red>, </><red>bloody </><b:red>pieces.</>'),
       ('UNHOLY_WORD', '<b:black>Your word of power is the last thing {target.name} hears.</>', '<b:black>{actor.name}''s word of power is the last thing you hear as your soul is torn apart.</>', '<b:black>{actor.name}''s word of power rends {target.name}''s soul to shreds.</>'),
       ('VAMPIRIC_BREATH', 'As you spew out a noxious <b:black>black cloud</> at {target.name}, you are filled with life!', '{actor.name}''s <b:black>black cloud guides you into the land of the dead!</>', '{actor.name} spews out a noxious <b:black>black cloud</> enveloping {target.name}, who seems quite dead!'),
       ('VICIOUS_MOCKERY', 'Your vicious words send {target.name} to a tearful grave!  They''ll never cross you again.', '{actor.name} cuts your heart so badly you die from heartbreak!', '{actor.name} unleashes a final vicious insult, killing {target.name}!'),
       ('WALL_OF_ICE', NULL::text, '<b:cyan>You impale yourself on the jagged wall of ice.</>', '<b:cyan>{target.name} impales {target.him}self on the jagged wall of ice.</>'),
       ('WATER_BLAST', 'You <b:blue>BLAST</> {target.name} into a <b:blue>watery grave!</>', 'The world grows dark as {actor.name} <b:blue>BLASTS</> you to a <b:blue>watery grave!</>', '{actor.name} <b:blue>BLASTS</> {target.name} into a <b:blue>watery grave!</>'),
       ('WRITHING_WEEDS', '<green>The weeds fully engulf {target.name} and choke {target.his} life away.</>', '<green>The weeds fully engulf you, choking your life away.</>', '<green>The weeds fully engulf {target.name}, choking {target.his} life away.</>')
     ) AS v(plain_name, to_caster, to_victim, to_room)
JOIN "Ability" a ON a.plain_name = v.plain_name
ON CONFLICT (ability_id) DO UPDATE
SET kill_to_caster = EXCLUDED.kill_to_caster,
    kill_to_victim = EXCLUDED.kill_to_victim,
    kill_to_room = EXCLUDED.kill_to_room
WHERE ("AbilityMessages".kill_to_caster, "AbilityMessages".kill_to_victim, "AbilityMessages".kill_to_room)
      IS DISTINCT FROM (EXCLUDED.kill_to_caster, EXCLUDED.kill_to_victim, EXCLUDED.kill_to_room);
